      }

      .hero__panel::before,
      .hero__panel::after {
        content: "";
        position: absolute;
        inset: auto;
        border-radius: 999px;
        filter: blur(0.5rem);
      }

      .hero__panel::before {
        width: 18rem;
        height: 18rem;
        right: -3rem;
        top: -2rem;
        background: rgba(31, 107, 92, 0.22);
      }

      .hero__panel::after {
        width: 12rem;
        height: 12rem;
        left: -2rem;
        bottom: -3rem;
        background: rgba(200, 107, 66, 0.16);
      }

      .hero-visual {
        position: absolute;
        inset: 1.5rem;
        display: grid;
        grid-template-columns: 1.2fr 0.9fr;
        gap: 1rem;
      }

      .hero-visual__main,
      .hero-visual__stack > div {
        border-radius: var(--radius-lg);
        overflow: hidden;
      }

      .hero-visual__main {
        background: linear-gradient(180deg, #ddcfba 0%, #c5a482 100%);
      }

      .hero-visual__stack {
        display: grid;
        gap: 1rem;
      }

      .hero-visual__stack > div:nth-child(1) {
        background: linear-gradient(180deg, #1f6b5c 0%, #133f36 100%);
      }

      .hero-visual__stack > div:nth-child(2) {
        background: linear-gradient(180deg, #f0ebe1 0%, #ddd2bf 100%);
      }

      .hero-visual__caption {
        position: absolute;
        left: 1.5rem;
        right: 1.5rem;
        bottom: 1.5rem;
        display: flex;
        justify-content: space-between;
        align-items: end;
        gap: 1rem;
        padding: 1.1rem 1.2rem;
        border-radius: var(--radius-md);
        background: rgba(255, 255, 255, 0.78);
        backdrop-filter: blur(18px);
      }

      .hero-visual__caption span {
        display: block;
        color: var(--text-muted);
        font-size: 0.92rem;
      }

      .meta-list {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 1rem;
        margin-top: 1.75rem;
      }

      .meta-list li {
        padding: 1rem;
        border-radius: var(--radius-md);
        background: rgba(255, 255, 255, 0.58);
        border: 1px solid var(--line);
      }

      .meta-list strong {
        display: block;
        font-size: 1.35rem;
        margin-bottom: 0.35rem;
      }

      .section {
        margin-top: 2rem;
      }

      .section-header {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1rem;
      }

      .section-intro {
        margin: 0.55rem 0 0;
        max-width: 42rem;
        line-height: 1.6;
      }

      .product-grid,
      .deal-grid,
      .story-grid {
        display: grid;
        gap: 1rem;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .deal-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .story-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .product-card,
      .deal-card,
      .story-card {
        padding: 1rem;
      }

      .product-media,
      .story-media {
        width: 100%;
        aspect-ratio: 4 / 4.8;
        object-fit: cover;
        border-radius: var(--radius-lg);
        background: var(--surface-muted);
      }

      .story-media {
        aspect-ratio: 16 / 10;
      }

      .product-copy,
      .story-copy {
        padding-top: 1rem;
      }

      .product-link,
      .story-link {
        display: inline-block;
        text-decoration: none;
        border-radius: 0.6rem;
      }

      .price-row,
      .deal-meta {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 0.75rem;
        margin: 0.7rem 0;
      }

      .price {
        font-size: 1.2rem;
        font-weight: 700;
      }

      .badge {
        display: inline-flex;
        align-items: center;
        padding: 0.4rem 0.6rem;
        border-radius: 999px;
        background: rgba(31, 107, 92, 0.08);
        color: var(--brand-strong);
        font-size: 0.85rem;
        font-weight: 600;
      }

      .product-actions {
        display: flex;
        gap: 0.75rem;
        margin-top: 1rem;
      }

      .product-actions > * {
        flex: 1;
      }

      .deal-card {
        display: grid;
        gap: 1.25rem;
        min-height: 17rem;
      }

      .deal-card__icon {
        width: 3rem;
        height: 3rem;
        display: grid;
        place-items: center;
        border-radius: 1rem;
        background: rgba(31, 107, 92, 0.1);
        color: var(--brand-strong);
      }

      .deal-card__icon svg {
        width: 1.5rem;
        height: 1.5rem;
        fill: currentColor;
      }

      .deal-card__footer {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
        margin-top: auto;
      }

      .story-card {
        overflow: hidden;
      }

      .story-meta {
        display: flex;
        align-items: center;
        gap: 0.7rem;
        margin-bottom: 0.8rem;
        color: var(--text-muted);
        font-size: 0.92rem;
      }

      .footer-panel {
        margin-top: 2rem;
        padding: 1.5rem;
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        gap: 1rem;
      }

      .footer-nav ul {
        display: flex;
        flex-wrap: wrap;
        gap: 0.35rem;
      }

      :focus-visible {
        outline: 3px solid #0f4ddf;
        outline-offset: 3px;
      }

      [hidden] {
        display: none !important;
      }

      @media (max-width: 1080px) {
        .hero,
        .product-grid,
        .deal-grid,
        .story-grid {
          grid-template-columns: 1fr 1fr;
        }

        .hero {
          grid-template-columns: 1fr;
        }

        .hero__panel {
          min-height: 22rem;
        }
      }

      @media (max-width: 820px) {
        .site-header__inner,
        .section-header,
        .footer-panel,
        .promo-banner {
          align-items: start;
        }

        .site-header__inner,
        .promo-banner,
        .section-header {
          flex-direction: column;
          display: flex;
        }

        .header-tools {
          width: 100%;
          flex-wrap: wrap;
        }

        .search-form {
          width: 100%;
        }

        .search-form input {
          min-width: 0;
          width: 100%;
        }

        .product-grid,
        .deal-grid,
        .story-grid,
        .meta-list,
        .hero-visual {
          grid-template-columns: 1fr;
        }

        .hero__copy {
          padding: 2rem;
        }

        .hero__panel {
          min-height: 28rem;
        }
      }

      @media (max-width: 480px) {
        .shell {
          width: min(calc(100% - 1rem), var(--max-width));
        }

        .hero__copy,
        .product-card,
        .deal-card,
        .story-card,
        .footer-panel {
          border-radius: var(--radius-lg);
        }

        .product-actions {
          flex-direction: column;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }

        *,
        *::before,
        *::after {
          animation: none !important;
          transition: none !important;
        }
      }

      @media (forced-colors: active) {
        :root {
          --surface: Canvas;
          --surface-strong: Canvas;
          --surface-muted: Canvas;
          --text: CanvasText;
          --text-muted: CanvasText;
          --line: ButtonText;
          --brand: Highlight;
          --brand-strong: Highlight;
          --accent: Highlight;
          --shadow: none;
        }

        .hero__panel::before,
        .hero__panel::after {
          display: none;
        }

        .button,
        .ghost-button,
        .header-action,
        .search-form,
        .promo-banner,
        .hero__copy,
        .hero__panel,
        .product-card,
        .deal-card,
        .story-card,
        .footer-panel,
        .meta-list li,
        .pill-list li {
          border: 1px solid ButtonText;
        }

        .badge,
        .eyebrow,
        .promo-banner__tag {
          border: 1px solid ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>

    <script>
      const featuredProducts = [
        {
          name: "Meridian Weekender",
          category: "Travel ready",
          price: "$248",
          badge: "Best seller",
          link: "#featured-products",
          imageAlt: "Tan weekender bag with structured handles and a front pocket.",
          palette: ["#dcc3a4", "#bb8f68", "#5b402c"]
        },
        {
          name: "Cloudline Knit Set",
          category: "Soft layers",
          price: "$168",
          badge: "Just in",
          link: "#featured-products",
          imageAlt: "Cream knit lounge set folded beside a matching scarf.",
          palette: ["#f1ece2", "#d7ccba", "#79685b"]
        },
        {
          name: "Aster Table Lamp",
          category: "Home edit",
          price: "$132",
          badge: "Limited run",
          link: "#featured-products",
          imageAlt: "Minimal table lamp with a rounded shade and warm brass stem.",
          palette: ["#ebdfcf", "#cca36f", "#5a4a3f"]
        },
        {
          name: "North Coast Runner",
          category: "Everyday movement",
          price: "$118",
          badge: "Members save 15%",
          link: "#featured-products",
          imageAlt: "Lightweight sand-colored running shoe with a gum sole.",
          palette: ["#d9dfd8", "#8aa08f", "#314942"]
        }
      ];

      const deals = [
        {
          title: "Bundle and save on travel layers",
          description:
            "Build a carry-on capsule with outerwear, soft knits, and accessories curated to move together.",
          kicker: "Save up to 30%",
          cta: "Shop travel sets"
        },
        {
          title: "48-hour living room refresh",
          description:
            "Warm lighting, sculptural storage, and tactile textiles selected to upgrade the nightly reset.",
          kicker: "Ends Friday",
          cta: "Explore home deals"
        },
        {
          title: "Members-only early access",
          description:
            "Unlock first access to new drops, styling notes, and exclusive pricing on seasonal favorites.",
          kicker: "Free to join",
          cta: "See member perks"
        }
      ];

      const stories = [
        {
          category: "Editorial",
          title: "How to style a seven-piece capsule for long weekends",
          description:
            "A packing formula built around texture, utility, and easy transitions from airport to dinner.",
          link: "#editorial"
        },
        {
          category: "Home journal",
          title: "The materials behind a calmer, brighter living space",
          description:
            "Design notes on balance, softness, and contrast from the Northstar interiors team.",
          link: "#editorial"
        },
        {
          category: "Field notes",
          title: "Meet the makers shaping our modern utility collection",
          description:
            "A closer look at the workshops, finishes, and details that define this season's launch.",
          link: "#editorial"
        }
      ];

      const navItems = ["New arrivals", "Women", "Men", "Home", "Journal"];

      function svgDataUrl(title, [start, end, accent]) {
        const svg = `
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 760" role="img" aria-label="${title}">
            <defs>
              <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0%" stop-color="${start}" />
                <stop offset="100%" stop-color="${end}" />
              </linearGradient>
            </defs>
            <rect width="640" height="760" rx="48" fill="url(#bg)" />
            <circle cx="500" cy="140" r="120" fill="${accent}" fill-opacity="0.12" />
            <circle cx="150" cy="590" r="140" fill="#ffffff" fill-opacity="0.14" />
            <rect x="110" y="170" width="420" height="360" rx="120" fill="#ffffff" fill-opacity="0.28" />
            <rect x="170" y="230" width="300" height="240" rx="90" fill="#ffffff" fill-opacity="0.32" />
            <rect x="150" y="560" width="340" height="32" rx="16" fill="#ffffff" fill-opacity="0.5" />
            <text x="50%" y="665" text-anchor="middle" font-family="Arial, sans-serif" font-size="34" fill="#172026">${title}</text>
          </svg>
        `;

        return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
      }

      function storyArt(title, start, end) {
        const svg = `
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 600">
            <defs>
              <linearGradient id="story" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0%" stop-color="${start}" />
                <stop offset="100%" stop-color="${end}" />
              </linearGradient>
            </defs>
            <rect width="960" height="600" rx="36" fill="url(#story)" />
            <rect x="90" y="130" width="340" height="290" rx="28" fill="#ffffff" fill-opacity="0.18" />
            <rect x="470" y="180" width="390" height="28" rx="14" fill="#ffffff" fill-opacity="0.35" />
            <rect x="470" y="245" width="300" height="24" rx="12" fill="#ffffff" fill-opacity="0.3" />
            <rect x="470" y="304" width="360" height="24" rx="12" fill="#ffffff" fill-opacity="0.3" />
            <rect x="470" y="363" width="250" height="24" rx="12" fill="#ffffff" fill-opacity="0.3" />
            <text x="90" y="530" font-family="Arial, sans-serif" font-size="34" fill="#172026">${title}</text>
          </svg>
        `;

        return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
      }

      function Header() {
        return `
          <header class="site-header">
            <div class="shell site-header__inner">
              <a class="brand" href="#maincontent">
                <span class="brand__mark" aria-hidden="true">N</span>
                <span>Northstar Atelier</span>
              </a>
              <nav class="site-nav" aria-label="Primary">
                <ul>
                  ${navItems
                    .map((item) => `<li><a href="#featured-products">${item}</a></li>`)
                    .join("")}
                </ul>
              </nav>
              <div class="header-tools">
                <form class="search-form" role="search" aria-label="Site">
                  <label class="sr-only" for="search">Search products and stories</label>
                  <input id="search" name="search" type="search" placeholder="Search products and stories" />
                  <button class="ghost-button" type="submit">Search</button>
                </form>
                <button class="header-action" type="button" aria-label="Open bag">Bag (2)</button>
              </div>
            </div>
          </header>
        `;
      }

      function PromoBanner() {
        return `
          <aside class="promo-banner" aria-labelledby="promo-title">
            <div>
              <div class="promo-banner__tag">
                <span aria-hidden="true">Spark</span>
                <span>Fresh drop</span>
              </div>
              <p id="promo-title"><strong>Complimentary shipping on orders over $150</strong> plus early access to the weekend edit.</p>
            </div>
            <a class="button" href="#deals">See deals</a>
            <button
              id="dismiss-promo"
              class="ghost-button"
              type="button"
              aria-label="Dismiss promo: Complimentary shipping on orders over 150 dollars plus early access to the weekend edit"
            >
              Dismiss
            </button>
          </aside>
        `;
      }

      function Hero() {
        return `
          <section class="hero" aria-labelledby="hero-heading">
            <div class="hero__copy">
              <span class="eyebrow">Spring / Summer 26</span>
              <h1 id="hero-heading">Design-led essentials for a more intentional every day.</h1>
              <p>
                Shop the latest edit of apparel, travel, and home pieces selected for tactile comfort,
                versatile styling, and a clean modern point of view.
              </p>
              <div class="hero-actions">
                <a class="button" href="#featured-products">Shop featured products</a>
                <a class="ghost-button" href="#editorial">Read the journal</a>
              </div>
              <ul class="pill-list" aria-label="Brand highlights">
                <li>Small-batch releases</li>
                <li>Free exchanges within 30 days</li>
                <li>Styling notes with every drop</li>
              </ul>
              <ul class="meta-list" aria-label="Key brand metrics">
                <li><strong>120+</strong><span>New arrivals curated this month</span></li>
                <li><strong>4.8/5</strong><span>Average rating across signature pieces</span></li>
                <li><strong>24 hr</strong><span>Dispatch on in-stock orders</span></li>
              </ul>
            </div>
            <div class="hero__panel">
              <div class="hero-visual" aria-hidden="true">
                <div class="hero-visual__main"></div>
                <div class="hero-visual__stack">
                  <div></div>
                  <div></div>
                </div>
              </div>
              <div class="hero-visual__caption">
                <div>
                  <strong>Curated around form, function, and softness.</strong>
                  <span>From city-ready bags to quiet home accents.</span>
                </div>
                <span class="badge">New season live</span>
              </div>
            </div>
          </section>
        `;
      }

      function SectionHeader(id, title, description, actionText, href) {
        return `
          <div class="section-header">
            <div>
              <h2 id="${id}">${title}</h2>
              <p class="section-intro">${description}</p>
            </div>
            <a class="ghost-button" href="${href}">${actionText}</a>
          </div>
        `;
      }

      function ProductCard(product) {
        const imageSrc = svgDataUrl(product.name, product.palette);

        return `
          <li>
            <article class="product-card">
              <img class="product-media" src="${imageSrc}" alt="${product.imageAlt}" />
              <div class="product-copy">
                <span class="badge">${product.category}</span>
                <h3>
                  <a class="product-link" href="${product.link}">${product.name}</a>
                </h3>
                <div class="price-row">
                  <span class="price">${product.price}</span>
                  <span>${product.badge}</span>
                </div>
                <p>Balanced proportions, premium materials, and a quietly distinctive finish.</p>
                <div class="product-actions">
                  <button class="button add-to-bag" type="button" data-product="${product.name}" aria-label="Add to Bag: ${product.name}">
                    Add to Bag
                  </button>
                  <button class="ghost-button" type="button" aria-label="Save for later: ${product.name}">
                    Save
                  </button>
                </div>
              </div>
            </article>
          </li>
        `;
      }

      function FeaturedProducts() {
        return `
          <section class="section" id="featured-products" aria-labelledby="featured-heading">
            ${SectionHeader(
              "featured-heading",
              "Featured products",
              "A focused assortment of wardrobe, travel, and home essentials designed to layer beautifully across the week.",
              "Browse all featured",
              "#featured-products"
            )}
            <ul class="product-grid">
              ${featuredProducts.map(ProductCard).join("")}
            </ul>
          </section>
        `;
      }

      function DealCard(deal) {
        return `
          <article class="deal-card">
            <div class="deal-card__icon" aria-hidden="true">
              <svg viewBox="0 0 24 24" focusable="false">
                <path d="M12 2 14.8 7.7 21 8.6l-4.5 4.4 1.1 6.2L12 16.3 6.4 19.2l1.1-6.2L3 8.6l6.2-.9Z"></path>
              </svg>
            </div>
            <div>
              <span class="badge">${deal.kicker}</span>
              <h3>${deal.title}</h3>
              <p>${deal.description}</p>
            </div>
            <div class="deal-card__footer">
              <span class="deal-meta">Curated promotion</span>
              <a class="ghost-button" href="#deals">${deal.cta}</a>
            </div>
          </article>
        `;
      }

      function Deals() {
        return `
          <section class="section" id="deals" aria-labelledby="deals-heading">
            ${SectionHeader(
              "deals-heading",
              "Deals and member perks",
              "Shop limited-time promotions built around complete looks and room resets rather than one-off markdowns.",
              "View all deals",
              "#deals"
            )}
            <div class="deal-grid">
              ${deals.map(DealCard).join("")}
            </div>
          </section>
        `;
      }

      function StoryCard(story, index) {
        const palettes = [
          ["#d7d1c7", "#bda68e"],
          ["#dce4df", "#91a99c"],
          ["#e8d9d1", "#c08c72"]
        ];
        const [start, end] = palettes[index % palettes.length];

        return `
          <article class="story-card">
            <img
              class="story-media"
              src="${storyArt(story.title, start, end)}"
              alt=""
            />
            <div class="story-copy">
              <div class="story-meta">
                <span>${story.category}</span>
                <span aria-hidden="true">/</span>
                <span>5 min read</span>
              </div>
              <h3>
                <a class="story-link" href="${story.link}">${story.title}</a>
              </h3>
              <p>${story.description}</p>
            </div>
          </article>
        `;
      }

      function Editorial() {
        return `
          <section class="section" id="editorial" aria-labelledby="editorial-heading">
            ${SectionHeader(
              "editorial-heading",
              "Editorial content",
              "Stories, styling notes, and behind-the-scenes features that connect the products to how people actually live with them.",
              "Visit the journal",
              "#editorial"
            )}
            <div class="story-grid">
              ${stories.map(StoryCard).join("")}
            </div>
          </section>
        `;
      }

      function Footer() {
        return `
          <footer class="shell">
            <div class="footer-panel">
              <div>
                <strong>Northstar Atelier</strong>
                <p>Modern retail for considered wardrobes, homes, and weekends away.</p>
              </div>
              <nav class="footer-nav" aria-label="Footer">
                <ul>
                  <li><a href="#featured-products">Shipping</a></li>
                  <li><a href="#editorial">Journal</a></li>
                  <li><a href="#deals">Membership</a></li>
                  <li><a href="#maincontent">Back to top</a></li>
                </ul>
              </nav>
            </div>
          </footer>
        `;
      }

      function App() {
        return `
          <a class="skip-link sr-only" href="#maincontent">Skip to main content</a>
          ${Header()}
          <main id="maincontent" class="shell" tabindex="-1">
            <p id="status-message" class="sr-only" aria-live="polite"></p>
            ${PromoBanner()}
            ${Hero()}
            ${FeaturedProducts()}
            ${Deals()}
            ${Editorial()}
          </main>
          ${Footer()}
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = App();
      }

      function announce(message) {
        const status = document.getElementById("status-message");
        status.textContent = "";
        window.setTimeout(() => {
          status.textContent = message;
        }, 20);
      }

      document.addEventListener("click", (event) => {
        const addButton = event.target.closest(".add-to-bag");
        const dismissButton = event.target.closest("#dismiss-promo");

        if (addButton) {
          announce(`${addButton.dataset.product} added to bag.`);
        }

        if (dismissButton) {
          const banner = dismissButton.closest(".promo-banner");
          banner.hidden = true;
          announce("Promo dismissed.");
        }
      });

      document.addEventListener("submit", (event) => {
        const form = event.target.closest(".search-form");

        if (!form) {
          return;
        }

        event.preventDefault();
        const query = form.querySelector("input").value.trim();
        announce(query ? `Search submitted for ${query}.` : "Search submitted.");
      });

      render();
    </script>
